    ('2fd4ea20-6784-52d2-bf9a-7f60d0d2f34b'::uuid, 'b3981abc-163f-5e7f-8425-d9518be21920'::uuid, 'Qu’est-ce qu’une guerre totale ?', 'mcq', '["Une guerre qui mobilise toutes les ressources d’un pays","Une guerre menée sur tous les continents","Une guerre sans prisonniers","Une guerre qui dure plus de quatre ans"]'::jsonb, 0, 'Militaires, économiques, scientifiques et morales.', 3),
    ('22016fec-f2ee-5563-8b9a-7be787e67bcf'::uuid, 'b3981abc-163f-5e7f-8425-d9518be21920'::uuid, 'Quel pays entre en guerre en avril 1917 aux côtés de l’Entente ?', 'mcq', '["Les États-Unis","L’Italie","Le Japon","L’Espagne"]'::jsonb, 0, 'Leur entrée compense la sortie de la Russie.', 4),
