    ('64146b04-fe97-5e5f-821f-f5ab93a7e9ee'::uuid, 'b3981abc-163f-5e7f-8425-d9518be21920'::uuid, 'Quel génocide est perpétré en 1915-1916 par le gouvernement jeune-turc ?', 'mcq', '["Le génocide des Arméniens","Le génocide des Tutsi","La Shoah","Le massacre de Katyn"]'::jsonb, 0, 'Environ 1,2 million de morts : le premier génocide du siècle.', 6),
