    ('e647c4b6-953f-55cd-96c0-7a1bff1731bb'::uuid, 'b3981abc-163f-5e7f-8425-d9518be21920'::uuid, 'La Société des Nations est créée après 1918 avec la participation des États-Unis.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le Sénat américain refuse d’y adhérer, ce qui affaiblit l’organisation.', 8),
    ('c6c8ecd5-6a73-5c89-bcde-431447d87f2d'::uuid, '77414f0a-4461-5d91-8b41-9ce4b92eece8'::uuid, 'Qu’est-ce qui caractérise un régime totalitaire ?', 'mcq', '["Il veut contrôler la société entière et transformer l’homme","Il limite son action à l’économie","Il organise des élections libres","Il respecte l’indépendance de la justice"]'::jsonb, 0, 'Travail, loisirs, famille et pensée sont encadrés.', 1),
    ('a24397b9-a61f-521d-8b4e-0e1ef47c8b5a'::uuid, '77414f0a-4461-5d91-8b41-9ce4b92eece8'::uuid, 'Quelle famine frappe l’Ukraine en 1932-1933 ?', 'mcq', '["L’Holodomor","La Grande Famine irlandaise","La famine du Bengale","La famine de la Volga de 1891"]'::jsonb, 0, 'Elle résulte de la collectivisation forcée des terres.', 2),
