    ('3943c8ff-4c1d-5e32-9908-2f9206a49a62'::uuid, '77414f0a-4461-5d91-8b41-9ce4b92eece8'::uuid, 'Quand Hitler devient-il chancelier d’Allemagne ?', 'mcq', '["Le 30 janvier 1933","Le 1er septembre 1939","Le 9 novembre 1918","Le 30 avril 1945"]'::jsonb, 0, 'Il obtient les pleins pouvoirs dans les semaines qui suivent.', 5),
    ('9306990c-c7b7-5cdb-8c52-802885123738'::uuid, '77414f0a-4461-5d91-8b41-9ce4b92eece8'::uuid, 'Que font les lois de Nuremberg de 1935 ?', 'mcq', '["Elles privent les Juifs de la citoyenneté allemande","Elles instaurent le suffrage universel","Elles interdisent le réarmement","Elles créent la Société des Nations"]'::jsonb, 0, 'L’antisémitisme devient une législation d’État.', 6),
    ('1f037f16-1164-58e0-93a4-40bfdd5cf66f'::uuid, '77414f0a-4461-5d91-8b41-9ce4b92eece8'::uuid, 'Qu’est-ce que la Nuit de Cristal de novembre 1938 ?', 'mcq', '["Un pogrom organisé contre les Juifs d’Allemagne","Une manifestation ouvrière à Berlin","Un défilé de la jeunesse hitlérienne","Une conférence internationale sur la paix"]'::jsonb, 0, 'Synagogues incendiées, commerces saccagés, arrestations massives.', 7),
    ('e622e2a8-aeaf-594f-b8bb-a94eb024928a'::uuid, '77414f0a-4461-5d91-8b41-9ce4b92eece8'::uuid, 'Le nazisme et le stalinisme poursuivent exactement les mêmes buts.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Les moyens se ressemblent, mais l’un se fonde sur la race, l’autre sur la classe.', 8),
    ('0d649ca7-6bd2-59b7-a6a1-982bf20882d6'::uuid, 'b7309ee0-716b-51d1-af0c-bd07dda9784e'::uuid, 'Combien de morts la Première Guerre mondiale coûte-t-elle à la France ?', 'mcq', '["Environ 1,4 million","Environ 400 000","Environ 3 millions","Environ 700 000"]'::jsonb, 0, 'Chaque commune élève un monument aux morts.', 1),
    ('2bf2a7ee-7e90-598e-8625-41eff35aab62'::uuid, 'b7309ee0-716b-51d1-af0c-bd07dda9784e'::uuid, 'Quand la crise économique mondiale atteint-elle la France ?', 'mcq', '["En 1931-1932","Dès octobre 1929","En 1936","En 1925"]'::jsonb, 0, 'Elle y arrive avec deux ans de décalage sur les États-Unis.', 2),
    ('3e3256a7-92ff-599c-9d78-94380a9eaa78'::uuid, 'b7309ee0-716b-51d1-af0c-bd07dda9784e'::uuid, 'Que se passe-t-il le 6 février 1934 à Paris ?', 'mcq', '["Des ligues d’extrême droite manifestent devant la Chambre des députés","Le Front populaire remporte les élections","Léon Blum est nommé président du Conseil","La France signe les accords de Locarno"]'::jsonb, 0, 'L’affrontement fait une quinzaine de morts.', 3),
    ('da033173-d5e6-565e-8a67-ffdf69fc3045'::uuid, 'b7309ee0-716b-51d1-af0c-bd07dda9784e'::uuid, 'Quelles forces composent le Front populaire ?', 'mcq', '["Socialistes, radicaux et communistes","Radicaux et ligues nationalistes","Communistes et Croix-de-Feu","Socialistes et monarchistes"]'::jsonb, 0, 'L’union naît de la peur du fascisme après février 1934.', 4),
    ('657ca6ce-c76d-5d6d-87f6-d0a8397c5750'::uuid, 'b7309ee0-716b-51d1-af0c-bd07dda9784e'::uuid, 'Qui dirige le gouvernement du Front populaire en 1936 ?', 'mcq', '["Léon Blum","Édouard Daladier","Maurice Thorez","Raymond Poincaré"]'::jsonb, 0, 'Il est le premier socialiste président du Conseil.', 5),
    ('e868edc2-c968-52b3-a7d7-b121caa3d5f6'::uuid, 'b7309ee0-716b-51d1-af0c-bd07dda9784e'::uuid, 'Quelle durée hebdomadaire de travail les accords de 1936 instaurent-ils ?', 'mcq', '["40 heures","35 heures","48 heures","44 heures"]'::jsonb, 0, 'Elle accompagne les congés payés et les conventions collectives.', 6),
    ('1b9bf6d9-8fcb-5a1a-b4b4-7c5422952627'::uuid, 'b7309ee0-716b-51d1-af0c-bd07dda9784e'::uuid, 'Combien de semaines de congés payés le Front populaire accorde-t-il ?', 'mcq', '["Deux semaines","Une semaine","Quatre semaines","Cinq semaines"]'::jsonb, 0, 'C’est la mesure la plus emblématique de 1936.', 7),
    ('a4c56d97-4ca7-507a-852c-1f4d71ad5c2b'::uuid, 'b7309ee0-716b-51d1-af0c-bd07dda9784e'::uuid, 'Les accords Matignon prévoient une hausse générale des salaires.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Environ 12 %, en plus des conventions collectives.', 8),
    ('f49ae79c-3b61-54f4-9e73-e402de49dea3'::uuid, '7e5af191-641a-5dc1-a550-a9caa519c68d'::uuid, 'Quelle date marque le début de la Seconde Guerre mondiale en Europe ?', 'mcq', '["Le 1er septembre 1939","Le 3 septembre 1939","Le 10 mai 1940","Le 22 juin 1941"]'::jsonb, 0, 'L’Allemagne envahit la Pologne ; France et Royaume-Uni déclarent la guerre deux jours plus tard.', 1),
    ('1a4a8d7f-279b-57ae-ab80-ee64a9c6431c'::uuid, '7e5af191-641a-5dc1-a550-a9caa519c68d'::uuid, 'Quel événement fait entrer les États-Unis dans le conflit ?', 'mcq', '["L’attaque de Pearl Harbor","La bataille de Stalingrad","Le débarquement de Normandie","L’invasion de la Pologne"]'::jsonb, 0, 'Le 7 décembre 1941, la flotte américaine du Pacifique est attaquée.', 2),
    ('bd8a4a8a-c7b9-5b22-a53a-e8793cec4e08'::uuid, '7e5af191-641a-5dc1-a550-a9caa519c68d'::uuid, 'Quelle bataille marque le tournant du front de l’Est ?', 'mcq', '["Stalingrad","Verdun","La Marne","Dunkerque"]'::jsonb, 0, 'La VIe armée allemande y capitule en février 1943.', 3),
