    ('a83e9659-3673-5c4f-81aa-15326c87c20b'::uuid, '4e4f149a-ca7b-59a2-a569-e10cdd43f499'::uuid, 'Quel texte adopté en 1944 sert de feuille de route à la refondation ?', 'mcq', '["Le programme du Conseil national de la Résistance","La Charte de l’ONU","Le préambule de 1958","Les accords Matignon"]'::jsonb, 0, 'Il est intitulé Les Jours heureux.', 1),
    ('26c99546-a96b-5748-8e4d-87ac06a30d6b'::uuid, '4e4f149a-ca7b-59a2-a569-e10cdd43f499'::uuid, 'Quand les Françaises votent-elles pour la première fois ?', 'mcq', '["En avril 1945","En 1944","En 1946","En 1936"]'::jsonb, 0, 'L’ordonnance leur accordant le droit de vote date du 21 avril 1944.', 2),
    ('df139acf-3941-54d7-a0c4-8367de092d10'::uuid, '4e4f149a-ca7b-59a2-a569-e10cdd43f499'::uuid, 'Quelle grande institution sociale est créée en octobre 1945 ?', 'mcq', '["La Sécurité sociale","Le RMI","Pôle emploi","Les allocations chômage"]'::jsonb, 0, 'Elle couvre maladie, accidents du travail, vieillesse et famille.', 3),
    ('8aed2758-fe21-5070-8bec-f2c405727f69'::uuid, '4e4f149a-ca7b-59a2-a569-e10cdd43f499'::uuid, 'Quelles entreprises sont nationalisées à la Libération ?', 'mcq', '["Renault, les charbonnages, EDF-GDF, Air France","Peugeot, Michelin, Danone","Les banques privées uniquement","Aucune entreprise"]'::jsonb, 0, 'L’État prend le contrôle de secteurs jugés stratégiques.', 4),
    ('93132138-88ee-5370-85d1-86f872d1085a'::uuid, '4e4f149a-ca7b-59a2-a569-e10cdd43f499'::uuid, 'Quand la Constitution de la IVe République est-elle adoptée ?', 'mcq', '["En octobre 1946","En 1944","En 1945","En 1958"]'::jsonb, 0, 'Un premier projet avait été rejeté en mai 1946.', 5),
    ('091439f9-195d-524c-a752-e56e74f73bae'::uuid, '4e4f149a-ca7b-59a2-a569-e10cdd43f499'::uuid, 'Quelle est la principale faiblesse de la IVe République ?', 'mcq', '["L’instabilité ministérielle","L’absence d’élections","L’absence de Parlement","Le refus de la construction européenne"]'::jsonb, 0, 'Plus de vingt gouvernements se succèdent en douze ans.', 6),
    ('8bc243e0-5343-507c-964f-a06d26e2fcfd'::uuid, '4e4f149a-ca7b-59a2-a569-e10cdd43f499'::uuid, 'Quel conflit emporte la IVe République en 1958 ?', 'mcq', '["La guerre d’Algérie","La guerre de Corée","La guerre d’Indochine","La crise de Suez"]'::jsonb, 0, 'La crise du 13 mai 1958 ramène de Gaulle au pouvoir.', 7),
    ('442f62f4-8c45-5b8c-98cc-b6a9cc2c1407'::uuid, '4e4f149a-ca7b-59a2-a569-e10cdd43f499'::uuid, 'De Gaulle a dirigé la IVe République pendant toute sa durée.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Hostile à ce régime, il démissionne dès janvier 1946.', 8),
    ('16511ae2-61e4-5e49-b42a-333a1283368a'::uuid, '39c0a7b7-54df-592d-8d1d-e31bf19a9c6b'::uuid, 'Quel événement ramène de Gaulle au pouvoir en 1958 ?', 'mcq', '["La crise du 13 mai 1958 en Algérie","Mai 1968","La guerre d’Indochine","La crise de Suez"]'::jsonb, 0, 'Il obtient les pleins pouvoirs pour rédiger une Constitution.', 1),
    ('6e2eb115-86f9-51c5-a186-593c0c3b0795'::uuid, '39c0a7b7-54df-592d-8d1d-e31bf19a9c6b'::uuid, 'Quand la Constitution de la Ve République est-elle approuvée ?', 'mcq', '["Le 28 septembre 1958","En octobre 1946","En 1962","En 1969"]'::jsonb, 0, 'Elle est adoptée par référendum.', 2),
    ('dd3bea4b-0383-58d5-ae7c-ad3e28213dd2'::uuid, '39c0a7b7-54df-592d-8d1d-e31bf19a9c6b'::uuid, 'Que change le référendum de 1962 ?', 'mcq', '["Le président est désormais élu au suffrage universel direct","Le Sénat est supprimé","Le président est élu par le Parlement","La durée du mandat passe à cinq ans"]'::jsonb, 0, 'La première élection de ce type a lieu en 1965.', 3),
    ('5c3571ee-017c-56c2-982a-97e289970d8d'::uuid, '39c0a7b7-54df-592d-8d1d-e31bf19a9c6b'::uuid, 'Quel article permet au président de soumettre un texte au référendum ?', 'mcq', '["L’article 11","L’article 16","L’article 49","L’article 5"]'::jsonb, 0, 'L’article 16 concerne les pouvoirs exceptionnels.', 4),
    ('6bccefd7-7da8-5916-8723-3d1612b6070b'::uuid, '39c0a7b7-54df-592d-8d1d-e31bf19a9c6b'::uuid, 'Quelle décision marque la politique d’indépendance nationale en 1966 ?', 'mcq', '["La sortie du commandement intégré de l’OTAN","L’entrée dans le pacte de Varsovie","Le renoncement à l’arme nucléaire","La rupture avec l’Allemagne"]'::jsonb, 0, 'La France conserve son alliance mais reprend son autonomie militaire.', 5),
    ('3fa9fe91-7127-56fe-bf2f-782e62ca5b9c'::uuid, '39c0a7b7-54df-592d-8d1d-e31bf19a9c6b'::uuid, 'Quel traité franco-allemand est signé en 1963 ?', 'mcq', '["Le traité de l’Élysée","Le traité de Rome","Le traité de Maastricht","Le traité de Versailles"]'::jsonb, 0, 'Il scelle la réconciliation entre les deux pays.', 6),
    ('09d55818-6c95-5b0a-9f67-d36806005414'::uuid, '39c0a7b7-54df-592d-8d1d-e31bf19a9c6b'::uuid, 'Qu’accordent les accords de Grenelle en mai 1968 ?', 'mcq', '["Une forte hausse du SMIG et des droits syndicaux","La semaine de 35 heures","La retraite à 60 ans","La cinquième semaine de congés payés"]'::jsonb, 0, 'La contestation dépassait toutefois les seules revendications salariales.', 7),
    ('b004a8d1-fdb7-5076-a98d-731270c3846f'::uuid, '39c0a7b7-54df-592d-8d1d-e31bf19a9c6b'::uuid, 'De Gaulle démissionne après avoir perdu le référendum d’avril 1969.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Il quitte le pouvoir dès le lendemain du scrutin.', 8),
    ('7d202ea4-85f0-5879-bf7f-265787be9783'::uuid, '365d5bdb-1c9d-55ab-90b6-457b1eaf6a52'::uuid, 'Qui a forgé l’expression « Trente Glorieuses » ?', 'mcq', '["Jean Fourastié","Alfred Sauvy","Raymond Aron","Fernand Braudel"]'::jsonb, 0, 'Elle désigne les trois décennies de forte croissance après 1945.', 1),
    ('06afe814-7bb6-501d-bae1-571203eb35fe'::uuid, '365d5bdb-1c9d-55ab-90b6-457b1eaf6a52'::uuid, 'Quel taux de croissance annuel moyen caractérise cette période en France ?', 'mcq', '["Plus de 5 %","Environ 1 %","Environ 2 %","Plus de 10 %"]'::jsonb, 0, 'Un rythme jamais retrouvé depuis.', 2),
    ('6a609178-ed75-5c88-856f-342b50f3b9ec'::uuid, '365d5bdb-1c9d-55ab-90b6-457b1eaf6a52'::uuid, 'Qu’est-ce que le baby-boom ?', 'mcq', '["Une forte hausse des naissances après 1945","Une vague d’immigration","Une politique de logement social","Une réforme scolaire"]'::jsonb, 0, 'Il fournit une main-d’œuvre nombreuse à la croissance.', 3),
    ('6f5427d7-6059-5e76-93e8-9fad3466cdb3'::uuid, '365d5bdb-1c9d-55ab-90b6-457b1eaf6a52'::uuid, 'Quel équipement se diffuse massivement dans les foyers durant cette période ?', 'mcq', '["Le réfrigérateur, la machine à laver, la télévision","L’ordinateur personnel","Le téléphone portable","Le four à micro-ondes uniquement"]'::jsonb, 0, 'La société de consommation se met en place.', 4),
    ('5b900867-7137-5918-a514-c03067f86a66'::uuid, '365d5bdb-1c9d-55ab-90b6-457b1eaf6a52'::uuid, 'Que sont les grands ensembles ?', 'mcq', '["De vastes quartiers de logements construits rapidement","Des zones industrielles","Des centres commerciaux","Des complexes agricoles"]'::jsonb, 0, 'Ils apportent d’abord un confort moderne inédit.', 5),
    ('50e81357-cc51-54ef-8077-5d3c4e5a9b45'::uuid, '365d5bdb-1c9d-55ab-90b6-457b1eaf6a52'::uuid, 'Quelle loi de 1967 autorise la contraception en France ?', 'mcq', '["La loi Neuwirth","La loi Veil","La loi Haby","La loi Royer"]'::jsonb, 0, 'La loi Veil dépénalise l’IVG en 1975.', 6),
    ('0cf849ee-7ccd-5cbf-a972-a79a3feb8d90'::uuid, '365d5bdb-1c9d-55ab-90b6-457b1eaf6a52'::uuid, 'Quel événement met fin aux Trente Glorieuses ?', 'mcq', '["Le choc pétrolier de 1973","Mai 1968","La chute du mur de Berlin","Le traité de Rome"]'::jsonb, 0, 'Il ouvre une période d’inflation et de chômage de masse.', 7),
    ('3aa8c561-4f16-5113-bc9e-a4fd57babc8d'::uuid, '365d5bdb-1c9d-55ab-90b6-457b1eaf6a52'::uuid, 'Le secteur tertiaire dépasse l’industrie durant les Trente Glorieuses.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le salariat devient la norme et les services se développent.', 8),
    ('a04d8798-1390-5ddc-8bf2-c7f63a23493b'::uuid, '47f6cabf-1f1f-55af-b99b-47f18eec5ff8'::uuid, 'Quelle réforme majeure Valéry Giscard d’Estaing fait-il adopter dès 1974 ?', 'mcq', '["La majorité à 18 ans","L’abolition de la peine de mort","Le quinquennat","La retraite à 60 ans"]'::jsonb, 0, 'La loi Veil sur l’IVG suit en 1975.', 1),
    ('6aa2adc8-5aef-5920-8766-3c730b8ac632'::uuid, '47f6cabf-1f1f-55af-b99b-47f18eec5ff8'::uuid, 'Quelle grande réforme marque l’arrivée de François Mitterrand en 1981 ?', 'mcq', '["L’abolition de la peine de mort","Le passage au quinquennat","La fin du service militaire","La loi sur la laïcité à l’école"]'::jsonb, 0, 'Elle est portée par Robert Badinter.', 2),
    ('eaae3e12-0f91-54b1-bae4-fdde09d9ba37'::uuid, '47f6cabf-1f1f-55af-b99b-47f18eec5ff8'::uuid, 'Qu’est-ce qu’une cohabitation ?', 'mcq', '["Un président et un Premier ministre d’orientations politiques opposées","Deux présidents en exercice","Un gouvernement sans majorité","Une alliance entre deux partis de même camp"]'::jsonb, 0, 'La France en a connu trois entre 1986 et 2002.', 3),
    ('3dabef0a-7995-531a-88a4-1b1178d2c697'::uuid, '47f6cabf-1f1f-55af-b99b-47f18eec5ff8'::uuid, 'Combien de temps dure le mandat présidentiel depuis la réforme de 2000 ?', 'mcq', '["Cinq ans","Sept ans","Quatre ans","Six ans"]'::jsonb, 0, 'Le quinquennat rend la cohabitation improbable.', 4),
    ('de8f4641-b8a4-5ce1-bf39-ff8cef4d1e52'::uuid, '47f6cabf-1f1f-55af-b99b-47f18eec5ff8'::uuid, 'Que transfèrent les lois Defferre de 1982 ?', 'mcq', '["Des compétences de l’État aux communes, départements et régions","Des compétences des régions vers l’État","Les impôts locaux à l’État","Le pouvoir législatif au président"]'::jsonb, 0, 'C’est l’acte fondateur de la décentralisation.', 5),
    ('d5aad537-c9cf-5c17-bfeb-4bdcbe275222'::uuid, '47f6cabf-1f1f-55af-b99b-47f18eec5ff8'::uuid, 'Qu’instaure la réforme constitutionnelle de 2008 en matière de justice ?', 'mcq', '["La question prioritaire de constitutionnalité","La suppression du Conseil constitutionnel","Le référendum obligatoire","La nomination des juges par le Parlement"]'::jsonb, 0, 'Elle permet à tout justiciable de contester une loi appliquée à son cas.', 6),
    ('cb9353db-83ed-51d1-91b4-0c0952debd72'::uuid, '47f6cabf-1f1f-55af-b99b-47f18eec5ff8'::uuid, 'Que prouve l’alternance de 1981 ?', 'mcq', '["Que la Constitution fonctionne quel que soit le camp au pouvoir","Que le président doit être issu de la droite","Que le Parlement domine l’exécutif","Que la cohabitation est impossible"]'::jsonb, 0, 'La Ve République survit à son fondateur et au changement de majorité.', 7),
    ('12b4c097-fd39-5c33-83ef-854282bba43a'::uuid, '47f6cabf-1f1f-55af-b99b-47f18eec5ff8'::uuid, 'Pendant une cohabitation, le président conserve la défense et les affaires étrangères.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le gouvernement conduit alors la politique intérieure.', 8)
  ) AS v(id, quiz_id, question, kind, options, correct_index, explanation, position)
-- Le quiz doit exister : si le NOT EXISTS ci-dessus a écarté un quiz (une
-- leçon en avait déjà un), ses questions ne partent pas dans le vide.
 WHERE EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.id = v.quiz_id)
ON CONFLICT (id) DO NOTHING;

-- 5. Sonde finale ----------------------------------------------------------
DO $$
DECLARE
  n_vides integer;
  n_chap  integer;
BEGIN
  SELECT count(*) INTO n_chap FROM public.chapters c
   JOIN public.subjects s ON s.id = c.subject_id
   WHERE s.slug IN ('histoire-geo');
  SELECT count(*) INTO n_vides FROM public.subjects s
   WHERE s.slug IN ('histoire-geo')
     AND NOT EXISTS (SELECT 1 FROM public.chapters c WHERE c.subject_id = s.id);
  IF n_vides > 0 THEN
    RAISE EXCEPTION 'Migration 291 incomplète : % matiere(s) encore sans chapitre', n_vides;
  END IF;
  RAISE NOTICE 'Migration 291 OK : % chapitres sur les matieres visees.', n_chap;
END $$;
